SELECT *
FROM Examination
WHERE `Examination Date` >= date((SELECT MAX(`Examination Date`) FROM Examination), '-1 month');

SELECT *
FROM Examination
WHERE "Examination Date" >= date((SELECT MAX("Examination Date") FROM Examination), '-1 month');

SELECT *
FROM Examination
WHERE date("Examination Date") >= date((SELECT MAX("Examination Date") FROM Examination), '-6 months');

SELECT *
FROM Examination
WHERE `Examination Date` >= (
    SELECT date(MAX(`Examination Date`), '-30 day')
    FROM Examination
);

SELECT *
FROM Examination
WHERE `Examination Date` >= (
    SELECT DATE(MAX(`Examination Date`), '-30 day')
    FROM Examination
);

SELECT *
FROM Examination
WHERE "Examination Date" >= DATE((SELECT MAX("Examination Date") FROM Examination), '-6 months');

SELECT *
FROM Examination
WHERE "Examination Date" >= DATE((SELECT MAX("Examination Date") FROM Examination), '-6 months');

SELECT *
FROM Examination
WHERE "Examination Date" >= (
    SELECT date(MAX("Examination Date"), '-6 month')
    FROM Examination
);

SELECT *
FROM Examination
WHERE "Examination Date" BETWEEN (
    SELECT date(max("Examination Date"), '-6 months') FROM Examination
) AND (
    SELECT max("Examination Date") FROM Examination
);

SELECT ID, "Examination Date"
FROM Examination
WHERE "aCL IgG" > 4.0;
